<div class="page-head"><div><span class="eyebrow">Access Control</span><h1>Reset Password</h1><p>Replace the password for this user without viewing or exposing the existing password.</p></div><a class="btn btn-secondary" href="<?=url('admin-users')?>">Back to Users</a></div>
<?php if($resetResult):?><section class="panel password-result" data-password-result><div><span class="eyebrow">Reset completed</span><h2>Copy this password now</h2><p>This temporary password is shown only once. Send it to <?=e($resetResult['name'])?> through your chosen secure channel.</p></div><div class="generated-password"><code data-generated-password><?=e($resetResult['password'])?></code><button class="btn btn-primary" type="button" data-copy-generated-password>Copy Password</button></div><?php if($resetResult['must_change']):?><p class="security-note">The user must choose a new password after signing in.</p><?php else:?><p class="security-note">The user can continue using this password until it is reset again.</p><?php endif;?></section><?php endif;?>
<section class="panel reset-user-summary"><div class="user-summary-avatar"><?=e(strtoupper(substr((string)$user['name'],0,1)))?></div><div><h2><?=e($user['name'])?></h2><p><?=e($user['email'])?></p><div class="summary-tags"><span><?=e(ucwords(str_replace('_',' ',$user['role'])))?></span><span><?=e($user['business_name']?:'Platform-wide')?></span><span><?=e(ucfirst($user['status']))?></span></div></div></section>
<form method="post" class="panel form-panel" data-password-reset-form><?=csrf_field()?><div class="form-grid two"><label>New password<div class="password-input-group"><input type="text" name="new_password" minlength="8" required autocomplete="new-password" data-new-password><button class="btn btn-secondary btn-small" type="button" data-generate-password>Generate</button></div><small>Use at least 8 characters. A 16-character secure password is recommended.</small></label><label>Confirm password<input type="text" name="confirm_password" minlength="8" required autocomplete="new-password" data-confirm-password></label></div><label class="checkbox-row"><input type="checkbox" name="must_change_password" value="1" <?=((int)$user['id']===(int)auth_id())?'disabled':'checked'?>> <span>Require this user to change the password after the next sign-in<?php if((int)$user['id']===(int)auth_id()):?> (not available when resetting your own password)<?php endif;?></span></label><?php if($user['status']!=='active'):?><div class="alert alert-warning">This user is inactive. The new password will be saved, but the user cannot sign in until the account is activated.</div><?php endif;?><div class="form-actions"><button class="btn btn-primary" type="submit">Reset Password</button><a class="btn btn-secondary" href="<?=url('admin-users')?>">Cancel</a></div></form>
